/* PARENT ve STUDENT ekranları — mobil öncelikli; ilk bakışta sıradaki servis ve durak. */
(function () {
  const D = window.DB, U = window.UI, T = window.TRIPUI, ic = window.icon, { esc, L, badge } = U;
  const A = window.ACTIONS, db = D.db, P = window.SCREENS.parent, St = window.SCREENS.student;

  function kids() { return D.childrenOfParent(APP.persona().parentId); }
  function childSwitch(ctx, cur, base) {
    const list = kids();
    return '<div class="child-switch" role="tablist" aria-label="Çocuk seçimi">' + list.map(s => '<a role="tab" aria-selected="' + (s.id === cur.id) + '" class="' + (s.id === cur.id ? "on" : "") + '" href="#/parent/' + base + "?child=" + s.id + '"><span class="avatar">' + U.initials(s.fullName) + "</span>" + esc(s.fullName.split(" ")[0]) + '<span class="xs muted">' + esc(s.grade) + "</span></a>").join("") + '<a href="#/parent/ogrenci-ekle" style="border-style:dashed;color:var(--ink-3)">' + ic("plus", 18) + "Öğrenci ekle</a></div>";
  }
  const pickChild = ctx => { const k = kids(); return k.find(s => s.id === +ctx.q.child) || k[0]; };

  /** Günlük servis kartı (DailyServiceEntryResponse §26) */
  function serviceCard(e, o) {
    o = o || {};
    const t = D.trip(e.tripId), loc = o.sim === "konum-yok" ? null : db.locations[e.tripId];
    // Veli/öğrenci rolü güzergâhın tüm duraklarını çekemez (stops uç noktası kapalı); haritada sadece kendi durağı.
    const stops = [{ id: e.stopId, name: e.stopName, mine: true }];
    const att = L.roster[e.attendanceStatus];
    let statusLine = badge(L.trip[e.status]);
    if (e.latestIncident && e.latestIncident.type === "DELAY" && e.status !== "COMPLETED") statusLine += " " + badge(L.incident.DELAY, "+" + e.latestIncident.delayMinutes + " dk");
    if (e.attendanceStatus !== "NONE") statusLine += " " + badge(att);
    if (e.absenceNotice) statusLine += " " + U.noticeBadge();
    let map = "";
    if (o.hero) {
      if (e.status === "IN_PROGRESS") map = loc ? U.mapPanel({ loc, stops, h: 220 }) : U.mapPanel({ empty: true, stops, h: 220, emptyIcon: "signalOff", emptyTitle: "Konum henüz alınamadı", emptyText: "Servis yolda ancak araçtan konum gelmiyor. Gecikme olursa bildirim alırsınız." });
      else if (e.status === "PLANNED") map = U.mapPanel({ empty: true, stops, h: 200, planned: true, emptyIcon: "clock", emptyTitle: "Sefer henüz başlamadı", emptyText: "Planlanan çıkış " + e.plannedStartTime + ". Servis yola çıkınca son konum burada görünür." });
    }
    const delayAlert = e.latestIncident && e.status !== "COMPLETED" && e.status !== "CANCELLED" ? '<div class="alert a-warn">' + ic(L.incident[e.latestIncident.type].i, 18) + "<div><b>" + L.incident[e.latestIncident.type].t + (e.latestIncident.delayMinutes ? ": yaklaşık " + e.latestIncident.delayMinutes + " dk" : "") + "</b>" + esc(e.latestIncident.note) + ' <span class="xs">(' + U.time(e.latestIncident.createdAt) + ")</span></div></div>" : "";
    const cancelAlert = e.status === "CANCELLED" ? '<div class="alert a-danger">' + ic("ban", 18) + "<div><b>Bu sefer iptal edildi</b>" + esc(e.cancellationReason || "") + "</div></div>" : "";
    const noticeBox = e.absenceNotice ? '<div class="alert a-notice">' + ic("hand", 18) + '<div style="flex:1"><b>“Servise binmeyecek” bildirdiniz</b>' + esc(e.absenceNotice.note || "Not eklenmedi") + " · " + U.time(e.absenceNotice.createdAt) + "<div class='xs'>Görevliye iletildi. Resmi yoklama yerine geçmez.</div></div></div>" : "";
    const actions = (e.canSubmitAbsenceNotice ? '<button class="btn btn-secondary btn-lg btn-block" data-act="notice-new" data-trip="' + e.tripId + '" data-st="' + o.studentId + '">' + ic("hand", 18) + "Servise binmeyecek</button>" : "") +
      (e.canWithdrawAbsenceNotice ? '<button class="btn btn-ghost btn-lg btn-block" data-act="notice-withdraw" data-id="' + e.absenceNotice.id + '">' + ic("undo", 18) + "Bildirimi geri al</button>" : "") +
      (o.role === "parent" && !e.canSubmitAbsenceNotice && !e.canWithdrawAbsenceNotice && (e.status === "PLANNED" || e.status === "IN_PROGRESS") && e.attendanceStatus !== "NONE" ? '<p class="xs muted">Yoklama girildiği için bildirim gönderilemez veya geri alınamaz.</p>' : "");
    if (!o.hero) return '<div class="card card-pad stack"><div class="between"><span class="row"><span class="badge b-muted">' + ic(L.dir[e.direction].i, 14) + L.dir[e.direction].s + '</span><span class="mono strong">' + esc(e.stopPlannedTime) + "</span></span>" + U.plate(e.vehiclePlate) + '</div><div class="row">' + statusLine + '</div><div class="small"><b>' + esc(e.stopName) + "</b> durağı · " + esc(e.routeName) + "</div>" + cancelAlert + delayAlert + noticeBox + actions + "</div>";
    return '<div class="hero-service"><div class="top"><div class="between"><span class="badge b-muted">' + ic(L.dir[e.direction].i, 14) + L.dir[e.direction].t + "</span>" + U.plate(e.vehiclePlate) + '</div><div class="when"><span class="tm">' + esc(e.stopPlannedTime) + '</span><span class="muted">durakta planlanan saat</span></div><div class="stopline">' + ic("pin", 22) + '<div><b>' + esc(e.stopName) + '</b><div class="small muted">' + esc(e.routeName) + " · servis çıkışı " + esc(e.plannedStartTime) + '</div></div></div><div class="row">' + statusLine + "</div>" + cancelAlert + delayAlert + noticeBox + "</div>" + map + (actions ? '<div class="card-pad stack" style="border-top:1px solid var(--line)">' + actions + "</div>" : "") + "</div>";
  }

  P.servisim = ctx => {
    const k = kids(); if (!k.length) return { title: "Bugünkü Servis", html: U.stateBlock("empty", { emptyIcon: "student", emptyTitle: "Aktif öğrenciniz yok", emptyText: "Başvurunuz onaylandığında servis bilgisi burada görünür.", emptyAction: '<a class="btn btn-primary" href="#/parent/ogrenci-ekle">Öğrenci ekle</a>' }) };
    const s = pickChild(ctx), entries = D.dailyService(s.id, "PARENT");
    const hero = entries.find(e => e.status === "IN_PROGRESS") || entries.find(e => e.status === "PLANNED") || entries[entries.length - 1];
    const html = childSwitch(ctx, s, "servisim") + (entries.length ? serviceCard(hero, { hero: true, studentId: s.id, role: "parent", sim: ctx.q.sim }) + '<div class="section-title"><h2>Günün diğer servisi</h2></div>' + entries.filter(e => e !== hero).map(e => serviceCard(e, { studentId: s.id, role: "parent" })).join("") : U.stateBlock("empty", { emptyIcon: "calendar", emptyTitle: "Bugün servis yok", emptyText: "Bu tarihte " + s.fullName + " için planlanmış sefer bulunmuyor." })) +
      '<div class="design-note"><b>Kaynak:</b> GET /api/students/{id}/daily-service + yoldaki sefer için GET /api/tracking/trips/{id}/latest (15 sn polling). Tahmini varış (ETA) API\'de yok; sadece son konum ve güncellenme zamanı gösterilir. ' + U.newApi("ETA") + "</div>";
    return { title: "Bugünkü Servis", mTitle: "Bugünkü Servis", mSub: "18 Kasım Çarşamba", html, narrow: true, stateHead: childSwitch(ctx, s, "servisim"), meta: { emptyIcon: "bus", emptyTitle: "Bugün servis yok", emptyText: "Bu tarih için sefer planlanmamış." } };
  };
  A["notice-new"] = el => { const tripId = +el.dataset.trip, st = +el.dataset.st, t = D.tripResponse(D.trip(tripId));
    U.dialog({ title: "Servise binmeyecek", icon: "hand", tone: "notice", sub: esc(D.student(st).fullName) + " · " + esc(t.routeName) + " " + esc(t.plannedStartTime),
      body: '<div class="alert a-info">' + ic("info", 18) + "<div>Bildirim şoför ve hostesin yolcu listesine düşer. <b>Resmi yoklama değildir</b>: öğrenci durağa gelirse binişi kaydedilir. Yoklama girilene veya sefer kapanana kadar geri alabilirsiniz.</div></div>" + U.field({ name: "note", label: "Not (isteğe bağlı)", type: "textarea", placeholder: "Örn. Doktor randevusu var, ben alacağım" }),
      ok: "Bildirimi gönder", okClass: "btn-primary", okIcon: "send", onSubmit: d => { D.api.submitNotice(tripId, st, d.note, APP.persona().userId); U.toast("Bildirim görevliye iletildi"); } }); };
  A["notice-withdraw"] = el => U.dialog({ title: "Bildirimi geri al", icon: "undo", tone: "warn", body: "<p>“Servise binmeyecek” bildiriminiz kaldırılır; görevli öğrenciyi durakta bekler.</p>", ok: "Geri al", onSubmit: () => { D.api.withdrawNotice(+el.dataset.id); U.toast("Bildirim geri alındı"); } });

  P["yoklama-gecmisi"] = ctx => { const s = pickChild(ctx); return { title: "Yoklama Geçmişi", html: childSwitch(ctx, s, "yoklama-gecmisi") + '<div class="alert a-muted">' + ic("info", 18) + "<div>Bir kayıt hatalıysa “İnceleme iste” ile yöneticiye iletebilirsiniz. Sonucu bildirim ve Taleplerim ekranında görürsünüz.</div></div>" + T.attendanceHistory(s.id, { review: true }), narrow: true, stateHead: childSwitch(ctx, s, "yoklama-gecmisi"), meta: { emptyIcon: "history", emptyTitle: "Yoklama kaydı yok" } }; };
  A["review-new"] = el => { const tripId = +el.dataset.trip, st = +el.dataset.st, cur = D.rosterStatus(tripId, st);
    U.dialog({ title: "Yoklama incelemesi iste", icon: "eye", tone: "warn", sub: esc(D.student(st).fullName) + " · kayıt: <b>" + L.roster[cur].t + "</b>",
      body: U.field({ name: "requestedStatus", label: "Olması gerektiğini düşündüğünüz durum (isteğe bağlı)", type: "select", placeholder: "Bilmiyorum / sadece kontrol edilsin", options: ["BOARDED", "DROPPED_OFF", "ABSENT", "NONE"].filter(x => x !== cur).map(x => [x, L.roster[x].t]) }) + U.field({ name: "reason", label: "Açıklama", type: "textarea", req: true }),
      ok: "Gönder", okIcon: "send", onSubmit: d => { if (!d.reason.trim()) return "Açıklama zorunludur."; D.api.createCorrection({ tripId, studentId: st, requestedStatus: d.requestedStatus || null, reason: d.reason }, APP.persona().userId, "PARENT"); U.toast("İnceleme talebi gönderildi"); } }); };

  P.taleplerim = ctx => {
    const p = APP.persona(), tab = ctx.q.tab || "durak";
    const mineStop = db.stopChanges.filter(r => r.requestedByUserId === p.userId), mineCorr = db.corrections.filter(c => c.requestedByUserId === p.userId);
    const pend = D.pendingChildrenOfParent(p.parentId);
    const tabs = '<div class="tabs">' + [["durak", "Durak değişikliği", mineStop.length], ["yoklama", "Yoklama incelemeleri", mineCorr.length], ["basvuru", "Öğrenci başvuruları", pend.length]].map(([k, l, n]) => '<a class="' + (tab === k ? "on" : "") + '" href="#/parent/taleplerim?tab=' + k + '">' + l + ' <span class="n">' + n + "</span></a>").join("") + "</div>";
    let body = "";
    if (tab === "durak") body = '<div class="row"><button class="btn btn-primary btn-lg" data-act="stopreq-new">' + ic("plus", 18) + "Durak değişikliği iste</button></div>" + (mineStop.length ? '<div class="stack">' + mineStop.map(r => '<div class="card card-pad stack"><div class="between"><b>' + esc(D.student(r.studentId).fullName) + " · " + L.dir[r.direction].s + "</b>" + badge(L.req[r.status]) + '</div><div class="small">Yeni durak: <b>' + esc(D.stop(r.requestedStopId).name) + "</b> (" + D.stop(r.requestedStopId).plannedTime + ") · " + U.date(r.effectiveDate) + " itibarıyla</div>" + (r.reason ? '<div class="small muted">“' + esc(r.reason) + "”</div>" : "") + (r.decisionNote ? '<div class="alert ' + (r.status === "APPROVED" ? "a-ok" : "a-danger") + '">' + ic(r.status === "APPROVED" ? "checkCircle" : "x", 18) + "<div><b>Yönetici notu</b>" + esc(r.decisionNote) + "</div></div>" : "") + '<div class="xs muted">Gönderildi ' + U.rel(r.createdAt) + "</div></div>").join("") + "</div>" : U.stateBlock("empty", { emptyIcon: "stop", emptyTitle: "Durak talebiniz yok" }));
    if (tab === "yoklama") body = mineCorr.length ? '<div class="card"><div class="list">' + mineCorr.map(c => T.corrRow(c, false)).join("") + "</div></div>" : U.stateBlock("empty", { emptyIcon: "history", emptyTitle: "İnceleme talebiniz yok", emptyText: "Yoklama Geçmişi ekranından talep açabilirsiniz." });
    if (tab === "basvuru") body = (pend.length ? pend.map(s => '<div class="card card-pad stack"><div class="between"><b>' + esc(s.fullName) + "</b>" + badge(L.contract.PENDING_APPROVAL) + '</div><div class="small muted">' + esc(s.schoolName) + " · " + esc(s.grade) + "</div><div class='small'>Yönetici onayladığında bildirim alırsınız. Bu sürede yeni başvuru açılamaz.</div></div>").join("") : '<div class="card card-pad"><b>Bekleyen başvuru yok</b><p class="small muted">Yeni çocuk eklemek için “Öğrenci Ekle”yi kullanın.</p><a class="btn btn-primary" style="align-self:flex-start;margin-top:8px" href="#/parent/ogrenci-ekle">' + ic("plus", 16) + "Öğrenci ekle</a></div>") +
      '<div class="alert a-muted">' + ic("bell", 18) + "<div><b>Reddedilen başvurular</b>Ret sonrası öğrenci kaydı pasife alınır ve bu listeden düşer; sonuç ve gerekçe <a href=\"#/parent/bildirimler\">Bildirimler</a>'de kalır. Örnek: “Öğrenci başvurunuz reddedildi — Gerekçe: Adres servis bölgesi dışında.”</div></div>";
    return { title: "Taleplerim", html: tabs + body, narrow: true, stateHead: tabs, meta: { emptyIcon: "inbox", emptyTitle: "Talebiniz yok" } };
  };
  A["stopreq-new"] = () => { const k = kids();
    const opts = db.stops.filter(s => D.route(s.routeId).direction === "AFTERNOON" && D.route(s.routeId).isActive).map(s => [s.id, D.route(s.routeId).name + " · " + s.name + " (" + s.plannedTime + ")"]);
    U.dialog({ title: "Durak değişikliği iste", icon: "stop", tone: "info", wide: true, body: '<div class="form-grid">' + U.field({ name: "studentId", label: "Öğrenci", type: "select", options: k.map(s => [s.id, s.fullName]), req: true }) + U.field({ name: "direction", label: "Yön", type: "select", options: [["AFTERNOON", "Dönüş (akşam)"], ["MORNING", "Gidiş (sabah)"]], req: true }) + U.field({ name: "requestedStopId", label: "Yeni durak", type: "select", options: opts, req: true, full: true, help: "Liste, seçilen öğrenci ve yön için aktif güzergâh duraklarıdır (GET /api/stop-change-requests/options)" }) + U.field({ name: "effectiveDate", label: "Geçerlilik tarihi", type: "date", value: "2026-11-24", req: true, help: "Bugün veya sonrası" }) + U.field({ name: "reason", label: "Açıklama", type: "textarea", full: true }) + "</div>",
      ok: "Talebi gönder", okIcon: "send", onSubmit: d => { if (d.effectiveDate < D.TODAY) return "Tarih bugünden önce olamaz."; D.api.createStopChange({ studentId: +d.studentId, direction: d.direction, requestedStopId: +d.requestedStopId, effectiveDate: d.effectiveDate, reason: d.reason }, APP.persona().userId); U.toast("Talebiniz yöneticiye iletildi"); } }); };

  P.odemeler = ctx => { const s = pickChild(ctx); return { title: "Ödemeler ve Ekstre", mTitle: "Ödemeler", html: childSwitch(ctx, s, "odemeler") + T.financePanel(s.id, false) + '<p class="xs muted">GET /api/contracts?studentId · /api/billing/charges · /api/payments · /api/students/{id}/statement — veli için salt okunur. Online ödeme kapsam dışı.</p>', stateHead: childSwitch(ctx, s, "odemeler"), meta: { emptyIcon: "wallet", emptyTitle: "Finans kaydı yok" } }; };

  P.cocuklarim = () => { const p = APP.persona(), k = kids(), pend = D.pendingChildrenOfParent(p.parentId);
    const html = k.map(s => { const as = db.assignments.filter(a => a.studentId === s.id && !a.validTo); return '<div class="card"><div class="card-head"><span class="avatar">' + U.initials(s.fullName) + '</span><div><h3>' + esc(s.fullName) + '</h3><div class="sub">' + esc(s.schoolName) + " · " + esc(s.grade) + '</div></div><div class="right">' + badge(L.contract.ACTIVE) + '</div></div><div class="card-pad stack-lg"><dl class="dl"><dt>Doğum tarihi</dt><dd>' + U.date(s.birthDate) + "</dd><dt>Adres</dt><dd>" + esc(s.addressLine + ", " + s.neighborhood) + "</dd><dt>Sağlık notu</dt><dd>" + esc(s.healthNote || "—") + '</dd></dl><div class="grid g-2" style="gap:8px">' + as.map(a => '<div class="card" style="padding:10px 12px;box-shadow:none"><div class="row small muted">' + ic(L.dir[a.direction].i, 14) + L.dir[a.direction].t + '</div><b>' + esc(D.stop(a.stopId).name) + '</b> <span class="mono small">' + D.stop(a.stopId).plannedTime + '</span><div class="xs muted">' + esc(D.route(a.routeId).name) + "</div></div>").join("") + '</div><div class="row"><a class="btn btn-secondary btn-sm" href="#/parent/servisim?child=' + s.id + '">Bugünkü servis</a><a class="btn btn-ghost btn-sm" href="#/parent/taleplerim">Durak değişikliği iste</a></div></div></div>'; }).join("") +
      pend.map(s => '<div class="card card-pad between"><div><b>' + esc(s.fullName) + '</b><div class="small muted">Başvuru yönetici onayında</div></div>' + badge(L.contract.PENDING_APPROVAL) + "</div>").join("") + '<p class="xs muted">GET /api/students (bağlı çocuklar) · GET /api/assignments?studentId=. Bilgiler salt okunurdur.</p>';
    return { title: "Çocuklarım", html, narrow: true, meta: { emptyIcon: "student" } }; };

  P["ogrenci-ekle"] = ctx => {
    const p = APP.persona(), pend = D.pendingChildrenOfParent(p.parentId), step = +(ctx.q.step || 1);
    if (pend.length) return { title: "Öğrenci Ekle", narrow: true, html: '<div class="card"><div class="state forbid"><div class="ill">' + ic("clock", 30) + "</div><h3>Bekleyen başvurunuz var</h3><p>" + esc(pend[0].fullName) + " başvurusu yönetici onayında. Sonuçlanana kadar yeni başvuru açılamaz (409).</p><a class='btn btn-secondary' href='#/parent/taleplerim?tab=basvuru'>Başvuruyu görüntüle</a></div></div>" };
    const steps = ["Öğrenci", "Okul ve adres", "Sözleşme", "Özet"];
    const nav = '<div class="steps">' + steps.map((s, i) => '<div class="s ' + (i + 1 < step ? "done" : i + 1 === step ? "on" : "") + '">' + (i + 1) + ". " + s + "</div>").join("") + "</div>";
    const forms = {
      1: '<div class="form-grid">' + U.field({ name: "fullName", label: "Öğrencinin adı soyadı", req: true, value: "Ece Korkmaz" }) + U.field({ name: "birthDate", label: "Doğum tarihi", type: "date", req: true, value: "2019-03-02" }) + U.field({ name: "tcNo", label: "T.C. kimlik no", req: true, help: "Başka öğrencide kayıtlıysa başvuru reddedilir (409)" }) + U.field({ name: "relationType", label: "Yakınlığınız", type: "select", options: [["ANNE", "Anne"], ["BABA", "Baba"], ["VASI", "Vasi"]] }) + U.field({ name: "healthNote", label: "Sağlık notu (isteğe bağlı)", type: "textarea", full: true }) + "</div>",
      2: '<div class="form-grid">' + U.field({ name: "schoolId", label: "Okul", type: "select", req: true, options: db.schools.filter(s => s.isActive).map(s => [s.id, s.name]), full: true, help: "Yalnızca aktif okullar listelenir" }) + U.field({ name: "grade", label: "Sınıf", req: true, value: "1-A" }) + U.field({ name: "parentPhone", label: "Telefonunuz", req: true, value: "0532 400 00 31" }) + U.field({ name: "district", label: "İlçe", req: true, value: "Merkezefendi" }) + U.field({ name: "neighborhood", label: "Mahalle", req: true, value: "Bağlarbaşı" }) + U.field({ name: "addressLine", label: "Açık adres", req: true, full: true, value: "Örnek Sk. No:1" }) + "</div>",
      3: '<div class="card card-pad stack" style="background:var(--surface-2)"><b>Servis hizmet sözleşmesi</b><p class="small">Aylık ücret: <b>' + U.money(db.settings.defaultMonthlyFee) + "</b> (kurum varsayılanı; yönetici onayda değiştirebilir). Sözleşme yönetici onayından sonra aktif olur.</p><p class='small muted'>Sözleşme metni kurum tarafından sağlanacak. Metin içeriği Sprint 2 kararıdır.</p></div><label class='check'><input type='checkbox' checked> Sözleşme koşullarını okudum ve kabul ediyorum.</label>",
      4: '<dl class="dl"><dt>Öğrenci</dt><dd>Ece Korkmaz · 02.03.2019</dd><dt>Okul</dt><dd>Yeşilvadi İlkokulu · 1-A</dd><dt>Adres</dt><dd>Örnek Sk. No:1, Bağlarbaşı, Merkezefendi</dd><dt>Ücret</dt><dd>' + U.money(db.settings.defaultMonthlyFee) + ' / ay</dd></dl><div class="alert a-info">' + ic("info", 18) + "<div>" + (kids().length ? "Bu ikinci çocuk başvurusudur. Mevcut çocuklarınızın servis bilgileri etkilenmez." : "İlk başvurunuz onaylanana kadar uygulamanın diğer bölümleri kapalı kalır.") + "</div></div>",
    };
    const html = '<div class="card"><div class="card-pad stack-lg">' + nav + "<h2 style='font-size:20px'>" + steps[step - 1] + "</h2>" + forms[step] + '</div><div class="card-foot">' + (step > 1 ? '<a class="btn btn-secondary" href="#/parent/ogrenci-ekle?step=' + (step - 1) + '">Geri</a>' : "") + '<span style="flex:1"></span>' + (step < 4 ? '<a class="btn btn-primary" href="#/parent/ogrenci-ekle?step=' + (step + 1) + '">Devam ' + ic("arrowR", 16) + "</a>" : '<button class="btn btn-primary" data-act="enroll-submit">' + ic("send", 16) + "Başvuruyu gönder</button>") + "</div></div>" + '<p class="xs muted">POST /api/parents/me/student-enrollments — bekleyen başvuru varsa 409; kurum varsayılan ücreti tanımlı değilse 409 (“Kayıtlar geçici olarak kapalı”).</p>';
    return { title: "Öğrenci Ekle", html, narrow: true };
  };
  A["enroll-submit"] = () => { D.api.enroll({ fullName: "Ece Korkmaz", birthDate: "2019-03-02", schoolId: 1, grade: "1-A", relationType: "ANNE", district: "Merkezefendi", neighborhood: "Bağlarbaşı", addressLine: "Örnek Sk. No:1" }, APP.persona().userId); U.toast("Başvurunuz yönetici onayına gönderildi"); APP.go("#/parent/taleplerim?tab=basvuru"); };

  P["onay-bekliyor"] = () => ({ title: "Onay bekleniyor", noState: true, narrow: true, html: '<div class="card"><div class="state"><div class="ill" style="background:var(--warn-bg);color:var(--warn)">' + ic("clock", 30) + '</div><h3>Başvurunuz yönetici onayında</h3><p>Arda Tan için yaptığınız kayıt alındı. Onaylandığında bildirim alacak ve servis bilgilerini görebileceksiniz. Bu sürede diğer menüler kapalıdır.</p><div class="steps" style="width:100%;max-width:420px"><div class="s done">Başvuru</div><div class="s on">Yönetici onayı</div><div class="s">Servis ataması</div></div><div class="row"><a class="btn btn-secondary" href="#/parent/bildirimler">Bildirimler</a><a class="btn btn-ghost" href="#/public/giris">Çıkış yap</a></div></div></div><div class="design-note"><b>Not:</b> Bu ekran ilk öz-kayıttan sonra veli kapısıdır (mevcut frontend gate). Prototipte örnek veli Gizem Tan durumu temsil edilir; menü bu ekranda yalnızca Bildirimler ve Çıkış içermelidir.</div>' });

  /* ───────── STUDENT ───────── */
  St.servisim = ctx => { const sid = APP.persona().studentId, s = D.student(sid), entries = D.dailyService(sid, "STUDENT");
    const hero = entries.find(e => e.status === "IN_PROGRESS") || entries.find(e => e.status === "PLANNED") || entries[0];
    const html = '<div class="row"><span class="avatar">' + U.initials(s.fullName) + '</span><div><b>' + esc(s.fullName) + '</b><div class="small muted">' + esc(s.schoolName) + " · " + esc(s.grade) + "</div></div></div>" + (hero ? serviceCard(hero, { hero: true, studentId: sid, role: "student", sim: ctx.q.sim }) + entries.filter(e => e !== hero).map(e => serviceCard(e, { studentId: sid, role: "student" })).join("") : U.stateBlock("empty", { emptyIcon: "calendar", emptyTitle: "Bugün servisin yok" })) +
      '<div class="alert a-muted">' + ic("info", 18) + "<div>Servise binmeyeceksen velinden bildirmesini iste. Öğrenci hesabı yalnızca görüntüler.</div></div>";
    return { title: "Bugünkü Servisim", html, narrow: true, meta: { emptyIcon: "bus", emptyTitle: "Bugün servisin yok" } }; };
  St.guzergahim = () => { const sid = APP.persona().studentId, as = db.assignments.filter(a => a.studentId === sid && !a.validTo), ds = D.dailyService(sid, "STUDENT");
    const html = as.map(a => { const e = ds.find(x => x.direction === a.direction); return '<div class="card"><div class="card-head"><span class="avatar" style="background:var(--brand-soft)">' + ic(L.dir[a.direction].i, 18) + '</span><div><h3>' + L.dir[a.direction].t + '</h3><div class="sub">' + (e ? esc(e.routeName) : "Güzergâh") + " · " + U.date(a.validFrom) + ' itibarıyla</div></div></div><div class="card-pad stack"><div class="hero-service" style="box-shadow:none"><div class="stopline">' + ic("pin", 22) + "<div><b>" + (e ? esc(e.stopName) : "Durak #" + a.stopId) + '</b><div class="small muted">Durakta planlanan saat <span class="mono strong">' + (e ? esc(e.stopPlannedTime) : "—") + "</span></div></div></div></div></div></div>"; }).join("") +
      '<div class="design-note"><b>API sınırı:</b> Öğrenci rolü <span class="mono">GET /api/routes/{id}/stops</span> çağıramaz ve AssignmentResponse sadece id döndürür. Durak adı/saati <span class="mono">GET /api/students/{id}/daily-service</span>’ten alınır (sefer olan günlerde). Tüm durak sırasını göstermek ve sefersiz günde ad göstermek için ' + U.newApi("AssignmentResponse’a routeName/stopName/plannedTime") + " önerilir.</div>";
    return { title: "Güzergâhım", html, narrow: true, meta: { emptyIcon: "route", emptyTitle: "Güzergâh ataman yok" } }; };
  St["yoklama-gecmisi"] = () => ({ title: "Yoklama Geçmişim", html: T.attendanceHistory(APP.persona().studentId, {}), narrow: true, meta: { emptyIcon: "history", emptyTitle: "Yoklama kaydın yok" } });
})();
